/**
 * Phase 0 golden tests — deterministic synthesizer extraction.
 *
 * Contract being proven (docs/guardian-reasoning-service.md §7 Phase 0):
 * `synthesizeHeartbeatAdvisory` reproduces the heartbeat's original
 * `pickRecommendation` output **byte-for-byte** across live / partial-down /
 * all-down fixtures.
 *
 * The GOLDEN literals below were generated by extracting the original
 * (pre-Phase-0) `pickRecommendation` from the heartbeat at the commit that
 * introduced this module's extraction target (git HEAD at extraction time)
 * and executing it against the same fixtures this file defines. They are
 * therefore an INDEPENDENT freeze of the original behaviour: the shared
 * implementation is compared against recorded output, not against a copy of
 * itself. Any wording drift — a changed adjective, a different disclosure —
 * fails these tests.
 *
 * The heartbeat route's own honesty suite (guardian-heartbeat.test.ts) still
 * pins the route alias behaviourally from the app side; its assertions and
 * these literals describe the same fixtures.
 */

import { describe, expect, it } from 'vitest';
import {
  synthesizeHeartbeatAdvisory,
  toGuardianSignals,
  evaluateGates,
  type HeartbeatMarketSnapshot,
} from '../index';

const TS = '2026-09-05T00:00:00.000Z';

function snapshot(opts: {
  defillamaLive?: boolean;
  pools?: HeartbeatMarketSnapshot['defillama']['pools'];
  coingeckoLive?: boolean;
  bitcoin?: number | null;
  paxGold?: number | null;
  worldBankLive?: boolean;
  inflation?: number | null;
}): HeartbeatMarketSnapshot {
  return {
    defillama: {
      live: opts.defillamaLive ?? true,
      pools: opts.pools ?? [],
    },
    coingecko: {
      live: opts.coingeckoLive ?? true,
      bitcoin: opts.bitcoin ?? (opts.coingeckoLive === false ? null : 65432),
      pax_gold: opts.paxGold ?? (opts.coingeckoLive === false ? null : 2411),
    },
    worldBank: {
      live: opts.worldBankLive ?? true,
      current_inflation: opts.inflation ?? (opts.worldBankLive === false ? null : 4.2),
    },
    timestamp: TS,
  };
}

/**
 * Goldens generated from the ORIGINAL pre-extraction implementation
 * (`git show <extraction-base>:apps/web/pages/api/agent/guardian-heartbeat.ts`
 * → `pickRecommendation` executed against the identical fixtures).
 * Regenerate ONLY when a reasoning wording change is intentionally reviewed;
 * a diff here is an on-chain-text change and must be treated as such.
 */
