const FIXTURES: Record<string, HeartbeatMarketSnapshot> = {
  allLive: snapshot({ inflation: 4.2, pools: [{ protocol: 'Mento', apy: 12.5, tvl: 5_000_000 }] }),
  highInflation: snapshot({ inflation: 7.8 }),
  coingeckoDown: snapshot({
    inflation: 4.2,
    coingeckoLive: false,
    bitcoin: null,
    paxGold: null,
    pools: [{ protocol: 'Mento', apy: 12.5, tvl: 5_000_000 }],
  }),
  worldBankDownStrongYield: snapshot({
    worldBankLive: false,
    inflation: null,
    pools: [{ protocol: 'Mento', apy: 12.5, tvl: 5_000_000 }],
  }),
  allDown: snapshot({
    defillamaLive: false,
    coingeckoLive: false,
    bitcoin: null,
    paxGold: null,
    worldBankLive: false,
    inflation: null,
  }),
  stableRegime: snapshot({ inflation: 2.0 }),
  weakYield: snapshot({
    worldBankLive: false,
    inflation: null,
    pools: [{ protocol: 'Mento', apy: 3.2, tvl: 5_000_000 }],
  }),
};

describe('Phase 0 golden: shared synthesizer ≡ original heartbeat output (byte-identical)', () => {
  for (const [name, snap] of Object.entries(FIXTURES)) {
    it(`${name} — every field byte-identical to the frozen original`, () => {
      const actual = synthesizeHeartbeatAdvisory(snap);
      const golden = GOLDEN[name];

      expect(actual.reasoning).toBe(golden.reasoning);
      expect(actual.action).toBe(golden.action);
      expect(actual.targetToken).toBe(golden.targetToken);
      expect(actual.confidence).toBe(golden.confidence);
    });
  }

  it('fixture set matches the golden set (no orphan fixtures/goldens)', () => {
    expect(Object.keys(FIXTURES).sort()).toEqual(Object.keys(GOLDEN).sort());
  });

  it('all-down golden keeps the honesty invariants (no fabricated figures)', () => {
    // Belt-and-braces on the freeze itself: the recorded original must
    // already satisfy the honesty contract, so the golden can never become
    // the vehicle for re-importing a fabricated default.
    const g = GOLDEN.allDown;
    expect(g.reasoning).not.toContain('$');
    expect(g.reasoning).not.toContain('65,000');
    expect(g.reasoning).not.toContain('2,400');
    expect(g.reasoning).not.toContain('3.1');
    expect(g.reasoning).toContain('no fallback market figures were used');
  });
});

describe('toGuardianSignals — provenance-honest bundle mapping', () => {
  it('live figures map to live signals with sources', () => {
    const signals = toGuardianSignals(FIXTURES.allLive);
    const keys = signals.map((s) => s.key);
    expect(keys).toContain('inflation.us.cpi');
    expect(keys).toContain('price.btc');
    expect(keys).toContain('price.paxg');
    expect(keys).toContain('yield.stable.topApy');
    expect(signals.every((s) => s.live && s.capturedAt === TS)).toBe(true);
  });

  it('unavailable sources never become live signals', () => {
    const signals = toGuardianSignals(FIXTURES.allDown);
    expect(signals).toHaveLength(0);
  });

  it('live-but-empty yield read yields no yield signal (not an outage)', () => {
    const signals = toGuardianSignals(FIXTURES.stableRegime);
    const keys = signals.map((s) => s.key);
    expect(keys).toContain('inflation.us.cpi');
    expect(keys).not.toContain('yield.stable.topApy');
  });

  it('every mapped signal is live with a named source', () => {
    for (const signals of Object.values(FIXTURES).map(toGuardianSignals)) {
      expect(signals.every((s) => s.live && s.source.length > 0)).toBe(true);
    }
  });
});

describe('evaluateGates — Layer A floor (pure, shared across surfaces)', () => {
  const passingGate = { allowed: true };
  const decliningGate = { allowed: false, reason: 'daily_limit_reached', detail: 'over cap' };

  it('aggregates declines with stable reason codes', () => {
    const verdict = evaluateGates([() => passingGate, () => decliningGate], { signals: [] });
    expect(verdict).toEqual({ status: 'declined', reasons: ['daily_limit_reached'] });
  });

  it('all-passing gates are eligible with no reasons', () => {
    const verdict = evaluateGates([() => passingGate, () => passingGate], { signals: [] });
    expect(verdict).toEqual({ status: 'eligible', reasons: [] });
  });
});
